from expansion_data import ROWS
for row in ROWS:
 kind='visit' if row['id']=='farm' else 'consult' if row['group']=='local' else 'inquiry'
 GUIDES[row['id']]=(kind,row['guide'][0],row['guide'][1])

def render_contact(s):
 kind,title,items=GUIDES[s['id']]
 kicker={'visit':'VISIT GUIDE','inquiry':'ENQUIRY GUIDE','consult':'CONSULTATION GUIDE'}[kind]
 rows=''.join(f'<li><h4>{e(a)}</h4><p>{e(b)}</p></li>' for a,b in items)
 return f'''<section class="section sample-contact contact-guide-section contact-guide-{kind}" id="contact"><div class="wrap contact-guide-grid"><div class="contact-guide-intro"><span class="eyebrow">{kicker}</span><h2>{s['contact']}</h2><p class="contact-guide-summary">{e(CONTACT_LEADS[s["id"]])}</p></div><aside class="contact-guide-details" aria-labelledby="contact-guide-title"><h3 id="contact-guide-title">{e(title)}</h3><ul>{rows}</ul></aside></div></section>'''
